def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    line_color, trail_color = 2, 8

    # Locate the straight divider. The marked object lies on one side of it.
    line = None
    for c in range(w):
        if all(g[r][c] == line_color for r in range(h)):
            line = ("v", c)
            break
    if line is None:
        for r in range(h):
            if all(g[r][c] == line_color for c in range(w)):
                line = ("h", r)
                break
    if line is None:
        return g

    # The most frequent non-divider color is the background; remaining
    # non-divider cells form the object whose far edge determines the trail.
    from collections import Counter
    counts = Counter(v for row in g for v in row if v != line_color)
    if not counts:
        return g
    background = counts.most_common(1)[0][0]
    obj = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] not in (line_color, background)]
    if not obj:
        return g

    orientation, pos = line
    if orientation == "v":
        mean = sum(c for r, c in obj) / len(obj)
        if mean > pos:
            trail_c = max(c for r, c in obj) + 1
        else:
            trail_c = min(c for r, c in obj) - 1
        if 0 <= trail_c < w:
            for r in range(h):
                g[r][trail_c] = trail_color
    else:
        mean = sum(r for r, c in obj) / len(obj)
        if mean > pos:
            trail_r = max(r for r, c in obj) + 1
        else:
            trail_r = min(r for r, c in obj) - 1
        if 0 <= trail_r < h:
            g[trail_r] = [trail_color] * w
    return g
